/**************************************************************************/
/**************************************************************************/
/**                                                                       */
/** ThreadX Test                                                          */
/**                                                                       */
/**   Stand-in FileX interface for the Module Manager load bounds test    */
/**                                                                       */
/**************************************************************************/
/**************************************************************************/

/* The Module Manager's file loader is compiled only when FileX is present, and it uses
   four FileX services on two FileX types. The load bounds test exercises that loader
   without FileX, so this header declares just those services and types; the test
   defines them over an in-memory file.  */

#ifndef FX_API_H
#define FX_API_H

#define FX_SUCCESS          0x00
#define FX_OPEN_FOR_READ    0
#define FX_NOT_FOUND        0x04

typedef struct FX_MEDIA_STRUCT
{
    ULONG   fx_media_id;
} FX_MEDIA;

typedef struct FX_FILE_STRUCT
{
    ULONG   fx_file_offset;
} FX_FILE;

UINT    fx_file_open(FX_MEDIA *media_ptr, FX_FILE *file_ptr, CHAR *file_name, UINT open_type);
UINT    fx_file_read(FX_FILE *file_ptr, VOID *buffer_ptr, ULONG request_size, ULONG *actual_size);
UINT    fx_file_seek(FX_FILE *file_ptr, ULONG byte_offset);
UINT    fx_file_close(FX_FILE *file_ptr);

#endif
